const update = $json;
const message = update.message || {};
const chat = message.chat || {};
const from = message.from || {};

function clean(value) {
  return value === undefined || value === null ? '' : String(value).trim();
}

function limaParts(date) {
  const formatter = new Intl.DateTimeFormat('en-CA', {
    timeZone: 'America/Lima',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: false,
  });
  return Object.fromEntries(formatter.formatToParts(date).filter((p) => p.type !== 'literal').map((p) => [p.type, p.value]));
}

function limaTimestamp(date) {
  const p = limaParts(date);
  return p.year + '-' + p.month + '-' + p.day + 'T' + p.hour + ':' + p.minute + ':' + p.second + '-05:00';
}

function limaDate(date) {
  const p = limaParts(date);
  return p.year + '-' + p.month + '-' + p.day;
}

const rawText = clean(message.text || message.caption || '');
let telegramFileId = null;
let fileMimeType = null;
let fileKind = null;

if (Array.isArray(message.photo) && message.photo.length) {
  const largest = [...message.photo].sort((a, b) => (b.file_size || 0) - (a.file_size || 0))[0];
  telegramFileId = largest.file_id;
  fileMimeType = 'image/jpeg';
  fileKind = 'photo';
} else if (message.document?.file_id && String(message.document.mime_type || '').startsWith('image/')) {
  telegramFileId = message.document.file_id;
  fileMimeType = message.document.mime_type;
  fileKind = 'document_image';
}

const chatId = clean(chat.id || from.id || 'unknown');
const msgId = clean(message.message_id || (chatId + ':' + Date.now()));
const receivedDate = new Date((message.date || Math.floor(Date.now() / 1000)) * 1000);

return [{
  json: {
    source: 'telegram',
    source_channel: 'telegram',
    input_type: telegramFileId && rawText ? 'mixed' : telegramFileId ? 'image' : 'text',
    chat_id: chatId,
    conversation_id: 'telegram:' + chatId,
    reply_chat_id: chatId,
    source_message_id: msgId,
    message_id: msgId,
    raw_text: rawText,
    subject: null,
    sender_name: clean([from.first_name, from.last_name].filter(Boolean).join(' ')) || from.username || null,
    sender_email: null,
    telegram_file_id: telegramFileId,
    telegram_file_mime_type: fileMimeType,
    telegram_file_kind: fileKind,
    image_url: null,
    has_image: Boolean(telegramFileId),
    received_at: receivedDate.toISOString(),
    received_at_utc: receivedDate.toISOString(),
    received_at_lima: limaTimestamp(receivedDate),
    reference_date_lima: limaDate(receivedDate),
    original_payload: update,
  },
}];

const input = $('Load Environment Variables').item.json;
const result = $json;
let imageUrl = null;

if (result.result?.file_path) {
  imageUrl = input.telegram_file_download_base + '/' + result.result.file_path;
}

return [{
  json: {
    ...input,
    image_url: imageUrl,
    has_image: Boolean(imageUrl),
    telegram_file_path: result.result?.file_path || null,
    telegram_image_binary_property: imageUrl ? 'telegram_image' : null,
  },
}];

function firstExistingNodeJson(names) {
  for (const name of names) {
    try {
      const value = $(name).item.json;
      if (value && Object.keys(value).length) return value;
    } catch (e) {}
  }
  return {};
}

function firstExistingNodeBinary(names) {
  for (const name of names) {
    try {
      const value = $(name).item.binary;
      if (value && Object.keys(value).length) return value;
    } catch (e) {}
  }
  return null;
}

const input = firstExistingNodeJson([
  'Normalize Telegram Image Binary',
  'Telegram API - Download Image Binary',
  'Attach Telegram File URL',
  'Load Environment Variables',
  'Normalize Telegram Event',
]);
const imageBinary = firstExistingNodeBinary(['Normalize Telegram Image Binary', 'Telegram API - Download Image Binary']);

let openDraft = null;
try {
  const d = $('Supabase - Get Open Draft for Expense').item.json;
  if (d && (d.id || d.draft_id || d['Draft ID'])) openDraft = d;
} catch (e) {}

let taxonomyContext = null;
let taxonomyPrompt = '{}';
try {
  const t = $('Supabase - Get AI Taxonomy Context').item.json;
  taxonomyContext = t.taxonomy_context || null;
  taxonomyPrompt = t.taxonomy_prompt || JSON.stringify(taxonomyContext || t || {}, null, 2);
} catch (e) {}

const referenceDateTime = input.received_at_lima || input.received_at || new Date().toISOString();
const referenceDate = input.reference_date_lima || String(referenceDateTime).slice(0, 10);
const hasImage = input.has_image === true && Boolean(imageBinary?.telegram_image);
const imageInstruction = hasImage
  ? 'Hay una imagen adjunta. Analiza el contenido visual del mensaje binario junto con el texto/caption.'
  : 'No hay imagen adjunta. Usa solo el texto y el contexto disponible.';

const prompt = [
  'Eres un extractor y normalizador de gastos personales para Peru.',
  '',
  'Devuelve un unico objeto JSON valido. No uses Markdown, no expliques tu razonamiento y no inventes datos.',
  '',
  'Contexto de entrada:',
  '- Fecha/hora de referencia en America/Lima: ' + referenceDateTime,
  '- Fecha de referencia en America/Lima: ' + referenceDate,
  '- Canal: ' + (input.source_channel || 'telegram'),
  '- Tipo de entrada: ' + (input.input_type || 'text'),
  '- Texto o caption recibido: ' + (input.raw_text || ''),
  '- Imagen adjunta: ' + (hasImage ? 'si, enviada como imageBinary en el mensaje humano' : 'no'),
  '- Instruccion de imagen: ' + imageInstruction,
  '- Draft abierto mas reciente, si existe: ' + JSON.stringify(openDraft || null),
  '',
  'Catalogo activo de categorias, subcategorias y merchant rules:',
  taxonomyPrompt,
  '',
  'Reglas generales:',
  '- Extrae solo un gasto por respuesta.',
  '- Si hay varios gastos claros en el mismo mensaje, extrae el gasto principal o el mas explicito.',
  '- Si el texto no describe un gasto, devuelve los campos principales en null, missing_fields con los campos criticos faltantes y confidence bajo.',
  '- Usa Peru como contexto por defecto.',
  '- amount debe ser numero decimal o null.',
  '- currency por defecto PEN si el gasto parece local en Peru.',
  '- expense_date debe estar en YYYY-MM-DD o null.',
  '- Si el usuario dice "hoy", usa la fecha de referencia en America/Lima.',
  '- Si el usuario dice "ayer", calcula la fecha usando America/Lima.',
  '- Si no hay fecha explicita, usa la fecha de referencia solo cuando el mensaje parece un gasto registrado en el momento.',
  '- No uses la fecha de referencia si el mensaje habla claramente de un gasto pasado pero no dice cuando.',
  '',
  'Reglas para entradas mixtas con imagen y caption:',
  '- Si hay imagen y caption/texto, el caption del usuario es contexto intencional y debe tener prioridad para categoria, subcategoria y proposito del gasto.',
  '- Usa la imagen principalmente para leer monto, fecha, metodo de pago, destinatario, numero de operacion y texto OCR.',
  '- No clasifiques como Transferencias personales solo porque un voucher de Yape/Plin/SIP muestra un destinatario, si el caption indica una compra o rubro concreto.',
  '- Si el caption dice Mercado, mercado, bodega, tienda, abarrotes, fruta, verdura, carne, pollo o huevos, clasifica como Supermercado y despensa > Mercado / bodega.',
  '- Si el caption dice Farmacia, botica, Inkafarma o Mifarma, clasifica como Salud > Farmacia.',
  '- Si el caption dice Taxi, movilidad, pasaje, micro o combi, clasifica segun Transporte.',
  '- Si el caption dice almuerzo, cena, desayuno, delivery o comida, clasifica segun Comida.',
  '- En vouchers de Yape/Plin/SIP, el destinatario puede ser merchant o contraparte, pero no debe dominar la categoria cuando el caption describe el rubro real.',
  '- Solo usa Transferencias personales cuando el texto/caption no indique compra, comercio, servicio o rubro concreto y la imagen sea claramente una transferencia a una persona.',
  '',
  'Reglas de drafts:',
  '- Si existe draft abierto y el mensaje actual parece una respuesta corta de aclaracion, combina ambos contextos para completar el gasto.',
  '- Si el mensaje actual describe claramente un gasto nuevo e independiente, prioriza el mensaje actual y no fuerces datos del draft anterior.',
  '',
  'Reglas de categorias:',
  '- Usa las categorias, subcategorias y merchant rules disponibles en el contexto.',
  '- No inventes categorias si existe una categoria razonable en la taxonomia.',
  '- category debe ser una categoria padre.',
  '- subcategory debe pertenecer coherentemente a esa category.',
  '- Si no hay una categoria suficientemente clara, category debe ser null y missing_fields debe incluir "category".',
  '- Primero evalua merchant_rules por prioridad. Si una regla aplica y no contradice el texto, usa default_category/default_subcategory/default_merchant.',
  '- Despues usa keywords de categorias/subcategorias como respaldo.',
  '- Si una merchant_rule contradice una senal mas especifica del texto, gana la senal mas especifica.',
  '',
  'Reglas de merchants y pago:',
  '- merchant debe ser el comercio, plataforma, proveedor o contraparte relevante.',
  '- Yape, Plin, SIP, tarjeta, efectivo, transferencia y bancos son payment_method, no merchant.',
  '- Si el texto dice "por Yape a Cinthia", payment_method es "Yape" y merchant puede ser "Cinthia" porque es la contraparte.',
  '- No uses palabras genericas como taxi, bus, micro, almuerzo, cena, desayuno, farmacia, mercado, delivery, comida o gasto como merchant si no hay marca.',
  '- Si aparece Yape, payment_method debe ser "Yape".',
  '- Si aparece Plin, payment_method debe ser "Plin".',
  '- Si aparece SIP, payment_method debe ser "SIP".',
  '- Si aparece efectivo o cash, payment_method debe ser "Efectivo".',
  '- Si aparece tarjeta de credito, payment_method debe ser "Tarjeta credito".',
  '- Si aparece tarjeta de debito, payment_method debe ser "Tarjeta debito".',
  '- Si aparece transferencia bancaria, payment_method debe ser "Transferencia".',
  '',
  'Reglas especificas para Peru:',
  '- "Yape a X", "Plin a X" o "transferi a X" suele ser Transferencias personales si no hay comercio o compra clara.',
  '- "Micro", "combi", "pasaje" o "microbus" es Transporte > Micro / combi / bus urbano, no taxi.',
  '- "Taxi" sin app es Transporte > Taxi.',
  '- Uber, Cabify, inDrive o DiDi Taxi son Transporte > Taxi por app.',
  '- Rappi o PedidosYa suelen ser Comida > Delivery, salvo que el texto indique supermercado, farmacia u otro rubro.',
  '- SmartFit es Fitness y deporte > Gimnasio, no Streaming.',
  '- OpenAI, ChatGPT, Cursor, Railway, Cloudflare, Namecheap o Supabase son Tecnologia y trabajo.',
  '- SANNA, Ferginest, laboratorio o analisis clinico van en Salud > Clinica / laboratorio.',
  '- Inkafarma, Mifarma o botica van en Salud > Farmacia.',
  '- Disney+, Netflix, Max o Prime Video son Suscripciones > Streaming video.',
  '- Para screenshots/vouchers de Yape, Plin, SIP o bancos, interpreta imagen y texto juntos.',
  '',
  'Reglas para missing_fields:',
  '- missing_fields solo puede contener: "amount", "category", "expense_date".',
  '- Incluye "amount" solo si no hay monto claro.',
  '- Incluye "category" solo si no hay categoria clara.',
  '- Incluye "expense_date" solo si no se puede determinar una fecha razonable.',
  '- No agregues "merchant", "subcategory", "payment_method" ni "description" a missing_fields.',
  '',
  'Reglas de confianza:',
  '- confidence debe ser un numero entre 0 y 1.',
  '- Usa confidence >= 0.85 cuando monto, categoria y fecha estan claros.',
  '- Usa confidence entre 0.70 y 0.84 cuando el gasto esta completo pero hay alguna ambiguedad menor.',
  '- Usa confidence < 0.70 cuando faltan datos criticos o el texto no parece un gasto.',
  '- No uses confidence para marcar campos como faltantes.',
  '',
  'Formato de salida obligatorio:',
  '{',
  '  "amount": number | null,',
  '  "currency": "PEN" | "USD" | "EUR" | null,',
  '  "category": string | null,',
  '  "subcategory": string | null,',
  '  "merchant": string | null,',
  '  "description": string | null,',
  '  "payment_method": "Yape" | "Plin" | "SIP" | "Efectivo" | "Tarjeta debito" | "Tarjeta credito" | "Transferencia" | "Otro" | null,',
  '  "expense_date": "YYYY-MM-DD" | null,',
  '  "missing_fields": ["amount" | "category" | "expense_date"],',
  '  "confidence": number,',
  '  "raw_ocr_text": string | null,',
  '  "document_type": string | null',
  '}',
].join('\n');

const outputItem = {
  json: {
    ...input,
    open_draft: openDraft,
    open_draft_id: openDraft?.id || openDraft?.draft_id || openDraft?.['Draft ID'] || null,
    taxonomy_context: taxonomyContext,
    taxonomy_prompt: taxonomyPrompt,
    chatInput: prompt,
    has_image_for_ai: hasImage,
    image_binary_property_for_ai: hasImage ? 'telegram_image' : null,
  },
};

if (imageBinary) {
  outputItem.binary = imageBinary;
}

return [outputItem];

const input = $('Build AI Extraction Context').item.json;
function parse(value) {
  if (!value) return {};
  if (typeof value === 'object') return value;
  let text = String(value).trim().replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```$/i, '').trim();
  const start = text.indexOf('{'), end = text.lastIndexOf('}');
  if (start >= 0 && end > start) text = text.slice(start, end + 1);
  try { return JSON.parse(text); } catch (e) { return { parse_error: e.message, raw_response: value }; }
}
function amount(value) {
  if (value === null || value === undefined || value === '') return null;
  if (typeof value === 'number') return Number.isFinite(value) ? Math.round(value * 100) / 100 : null;
  let s = String(value).trim().replace(/[^0-9,.-]/g, '');
  if (!s) return null;
  const hasComma = s.includes(','), hasDot = s.includes('.');
  if (hasComma && hasDot) s = s.lastIndexOf(',') > s.lastIndexOf('.') ? s.replace(/\./g, '').replace(',', '.') : s.replace(/,/g, '');
  else if (hasComma) s = s.replace(',', '.');
  const n = Number(s); return Number.isFinite(n) && n > 0 ? Math.round(n*100)/100 : null;
}
function normCurrency(v) { const s = String(v || '').toUpperCase(); if (s.includes('USD') || s.includes('DOLAR') || s.includes('DÓLAR') || s.includes('$')) return 'USD'; if (s.includes('EUR')) return 'EUR'; return 'PEN'; }
function normPayment(v) { const s = String(v || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, ''); if (s.includes('yape')) return 'Yape'; if (s.includes('plin')) return 'Plin'; if (s.includes('sip')) return 'SIP'; if (s.includes('efect') || s.includes('cash')) return 'Efectivo'; if (s.includes('debito') || s.includes('debit')) return 'Tarjeta débito'; if (s.includes('credito') || s.includes('credit')) return 'Tarjeta crédito'; if (s.includes('transfer')) return 'Transferencia'; return v || null; }
const parsed = parse($json.output || $json.text || $json);
const expense = parsed.expense || parsed;
const payload = {
  ...input,
  amount: amount(expense.amount),
  currency: normCurrency(expense.currency),
  category_name: expense.category || expense.category_name || null,
  subcategory_name: expense.subcategory || expense.subcategory_name || null,
  merchant_name: expense.merchant || expense.merchant_name || null,
  description: expense.description || null,
  payment_method: normPayment(expense.payment_method),
  expense_date: expense.expense_date || null,
  missing_fields: Array.isArray(expense.missing_fields) ? expense.missing_fields.filter(v => ['amount','category','expense_date'].includes(v)) : [],
  confidence: Math.max(0, Math.min(1, Number(expense.confidence ?? 0.75))),
  raw_ocr_text: expense.raw_ocr_text || null,
  document_type: expense.document_type || null,
  source_image_url: input.telegram_file_path ? 'telegram:' + input.telegram_file_path : null,
  open_draft_id: input.open_draft_id || null,
  ai_payload: expense,
};
if (!payload.amount && !payload.missing_fields.includes('amount')) payload.missing_fields.push('amount');
if (!payload.category_name && !payload.missing_fields.includes('category')) payload.missing_fields.push('category');
if (!payload.expense_date && !payload.missing_fields.includes('expense_date')) payload.missing_fields.push('expense_date');
payload.is_complete = payload.missing_fields.length === 0 && payload.confidence >= 0.8;
payload.status_to_save = payload.is_complete ? 'confirmed' : 'awaiting_clarification';
payload.clarification_question = payload.missing_fields.includes('amount') ? 'Me falta el monto. ¿Cuánto fue?' : payload.missing_fields.includes('expense_date') ? 'Me falta la fecha. ¿Fue hoy u otra fecha?' : payload.missing_fields.includes('category') ? 'Me falta la categoría. ¿Cómo quieres clasificarlo?' : `Entendí un gasto de S/ ${payload.amount} en ${payload.category_name || 'sin categoría'}. ¿Lo registro así?`;
return [{ json: payload }];

let item = $json;
let msg = 'Listo.';

if (item.id && item.status === 'awaiting_clarification') {
  msg = `Tengo el gasto como borrador. ${item.clarification_question || 'Me falta confirmar algunos datos.'}`;
} else if (item.id && item.amount) {
  const detail = item.subcategory_name || item.category_name || 'gasto';
  msg = `✅ Registré S/ ${item.amount} en ${detail}${item.merchant_name ? ' · ' + item.merchant_name : ''}.`;
} else if (item.message) {
  msg = item.message;
}

try {
  const input = $('Build AI Extraction Context').item.json;
  item.reply_chat_id = input.reply_chat_id;
  item.chat_id = input.chat_id;
} catch (e) {}

return [{
  json: {
    ...item,
    delivery_chat_id: item.reply_chat_id || item.chat_id || $env.TELEGRAM_CHAT_ID,
    message: msg
  }
}];

const input = $json;

function requiredEnv(name) {
  const value = String($env[name] || '').trim();
  if (!value) {
    throw new Error('Missing required environment variable: ' + name);
  }
  return value;
}

const telegramAccessToken = requiredEnv('TELEGRAM_ACCESS_TOKEN');
const telegramBotApiBase = 'https://api.telegram.org/bot' + telegramAccessToken;
const telegramFileDownloadBase = 'https://api.telegram.org/file/bot' + telegramAccessToken;

return [{
  json: {
    ...input,
    telegram_get_file_url: telegramBotApiBase + '/getFile',
    telegram_file_download_base: telegramFileDownloadBase,
    fallback_reply_chat_id: $env.TELEGRAM_CHAT_ID || null,
    runtime_config_loaded: true,
  },
}];

const item = $input.item;
const binary = item.binary || {};
const image = binary.telegram_image;

function imageMimeType() {
  const declared = String(item.json.telegram_file_mime_type || '').toLowerCase();
  if (declared.startsWith('image/')) return declared;

  const extension = String(image?.fileExtension || image?.fileName || item.json.telegram_file_path || '').toLowerCase();
  if (extension.endsWith('.png') || extension === 'png') return 'image/png';
  if (extension.endsWith('.webp') || extension === 'webp') return 'image/webp';
  if (extension.endsWith('.gif') || extension === 'gif') return 'image/gif';
  if (extension.endsWith('.jpg') || extension.endsWith('.jpeg') || extension === 'jpg' || extension === 'jpeg') return 'image/jpeg';

  return 'image/jpeg';
}

if (image) {
  binary.telegram_image = {
    ...image,
    mimeType: imageMimeType(),
    fileExtension: image.fileExtension || 'jpg',
    fileName: image.fileName || 'telegram-image.jpg',
  };
}

return [{
  json: {
    ...item.json,
    telegram_image_mime_type_for_ai: binary.telegram_image?.mimeType || null,
  },
  binary,
}];
